draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw character
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // head movement
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30);
  ctx.lineTo(W/2, H/2 - 60 + 20 * Math.sin(t));
  ctx.stroke();

  // arm movement
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 - 40 + 20 * Math.cos(t), H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 + 40 + 20 * Math.cos(t), H/2 + 20);
  ctx.stroke();

  // leg movement
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2 + 20 + 10 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.restore();
}
